#!/usr/bin/env python3
"""Rebuild Jake's static GitHub Pages portfolio from content/projects.json.

Usage: python scripts/build_site.py
External packages and external content/CDN requests are not required.
"""
import json,html,pathlib
from datetime import datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'content/projects.json').read_text(encoding='utf-8'))
P=DATA['projects']; lookup={p['slug']:p for p in P}
assert len(P)==len(lookup)
ESC=lambda s:html.escape(str(s),quote=True)
# With repository named it-portfolio, relative paths also work on GitHub Pages' subpath.
def header(prefix=''):
    return f'''<a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="wrap nav-inner"><a class="brand" href="{prefix}index.html"><span class="brandmark" aria-hidden="true">JA</span><span>JAKE ALFORD<small>IT / PROJECT PORTFOLIO</small></span></a><nav class="navlinks" aria-label="Main"><a class="hide-mobile" href="{prefix}index.html#projects">Projects</a><a class="hide-mobile" href="{prefix}index.html#skills">Skills</a><a class="hide-mobile" href="{prefix}index.html#about">About</a><a class="nav-contact" href="{prefix}index.html#contact">Contact</a></nav></div></header>'''
def footer(prefix=''):
    return f'''<footer class="footer"><div class="wrap footer-inner"><span>© Jake Alford · Independent IT projects · Coventry, UK</span><span>Built to show what I've actually done, tested and learned. <a href="{prefix}portfolio.pdf">Portfolio PDF</a></span></div></footer>'''
def page(title,body,prefix='',desc='Jake Alford IT project portfolio'):
    return f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{ESC(desc)}"><meta name="theme-color" content="#102b39"><title>{ESC(title)} | Jake Alford IT Portfolio</title><link rel="stylesheet" href="{prefix}assets/styles.css"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"></head><body>{header(prefix)}<main id="main">{body}</main>{footer(prefix)}<script defer src="{prefix}assets/filter.js"></script></body></html>'''
def card(p):
    return f'''<article class="project-card" data-project-card data-category="{ESC(p['category'])}"><div class="card-top"><span class="tag">{ESC(p['category'])}</span><span class="status">{ESC(p['status'])}</span></div><h3>{ESC(p['title'])}</h3><p>{ESC(p['short'])}</p><div class="card-footer"><a class="text-link" href="projects/{ESC(p['slug'])}.html">Read the case study</a><span class="arrow" aria-hidden="true">↗</span></div></article>'''
featured=[lookup[s] for s in DATA['featured']]
# Brief verified numbers; do not invent or inflate these.
hero='''<section class="hero"><div class="wrap hero-layout"><div><div class="eyebrow">Coventry, UK &nbsp;/&nbsp; Independent IT projects</div><h1>Building, fixing and <em>learning</em> how IT works.</h1><p class="lead">I'm Jake. Outside of work, I've built my own home lab to learn about servers, networks, Linux and software. These are the things I've actually set up, tested and worked through.</p><div class="actions"><a class="btn btn-main" href="#projects">Explore my projects ↗</a><a class="btn btn-outline" href="portfolio.pdf" download>Download portfolio PDF ↓</a></div></div><div class="hero-panel" aria-label="Simplified home lab service diagram"><div class="terminal-row" aria-hidden="true"><span></span><span></span><span></span></div><div class="hero-panel-head">A REAL HOME LAB / SIMPLIFIED VIEW</div><div class="diagram-card"><span class="diagram-label">Connection</span><b>FibreNest gateway → ASUS router</b><small>LAN routing, DNS, double NAT investigation</small></div><div class="connector"></div><div class="diagram-card"><span class="diagram-label">Wired network</span><b>Aruba managed PoE switch</b><small>Clients, server and network troubleshooting</small></div><div class="connector"></div><div class="diagram-two"><div class="diagram-card"><span class="diagram-label">Server</span><b>Windows Server 2022</b><small>Hyper-V / Debian VMs</small></div><div class="diagram-card"><span class="diagram-label">Services</span><b>Pi-hole + Uptime Kuma</b><small>DNS and availability alerts</small></div></div><div class="panel-foot"><span>NOT A COMPLETE INVENTORY</span><span>NO PRIVATE ADDRESSES</span></div></div></div></section>'''
metrics='''<section class="metric-strip" aria-label="Recorded technical results"><div class="wrap metric-grid"><div class="metric"><strong>55 / 55</strong><span>Automated HomeLab Manager API tests passed in a recorded run</span></div><div class="metric"><strong>≈850 Mbps</strong><span>Wired speed test observed after switch troubleshooting</span></div><div class="metric"><strong>20 TPS</strong><span>Local Minecraft server result in a one-player test</span></div></div></section>'''
cats=['All','Infrastructure','Networking','Software','Operations','Security','Server hosting','Experiments','Hardware','Planning']
buttons=''.join(f'<button class="filter-btn{" is-active" if cat=="All" else ""}" data-filter="{ESC(cat)}" type="button" aria-pressed="{"true" if cat=="All" else "false"}">{ESC(cat)}</button>' for cat in cats)
projects=f'''<section class="section" id="projects"><div class="wrap"><div class="section-head"><div><div class="eyebrow">01 / PROJECT WORK</div><h2>What I've been working on.</h2></div><p class="section-desc">The working systems come first. I've also included prototypes and experiments, but they're labelled clearly rather than presented as finished deployments.</p></div><div class="filters" aria-label="Filter projects">{buttons}<input class="mini-search" type="search" id="project-search" aria-label="Search projects" placeholder="Search projects..."></div><div class="project-grid">{''.join(card(p) for p in featured)}{''.join(card(p) for p in P if p not in featured)}</div><div id="empty-state" class="empty-state" role="status">No projects match that filter. Try another category or search.</div><p class="simple-callout">Project statuses are based on tests and configuration work, not plans. Updated {ESC(DATA['last_reviewed'])}.</p></div></section>'''
skills='''<section class="section section-soft" id="skills"><div class="wrap"><div class="section-head"><div><div class="eyebrow">02 / SKILLS</div><h2>Tools I've actually used.</h2></div><p class="section-desc">I've learned these through working on real devices, virtual machines and applications in my own time.</p></div><div class="skill-grid"><div class="skill-box"><b>Systems & virtualisation</b><p>Windows Server 2022, Hyper-V, Debian / Ubuntu, Raspberry Pi OS, SSH and virtual networking.</p></div><div class="skill-box"><b>Networking & access</b><p>TCP/IP, DNS, Pi-hole, managed PoE switching, Tailscale, NAT and Wi-Fi troubleshooting.</p></div><div class="skill-box"><b>Monitoring & security</b><p>Uptime Kuma, Discord alerts, Vaultwarden, two-factor authentication and role-based access.</p></div><div class="skill-box"><b>Development & testing</b><p>Kotlin, Jetpack Compose, C#, .NET 10, SQLite, Android Studio, ADB, Postman and API tests.</p></div></div></div></section>'''
method='''<section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">03 / APPROACH</div><h2>How I troubleshoot.</h2></div><p class="section-desc">I learn a lot from things not working first time. This is the approach I try to follow when something goes wrong.</p></div><div class="steps"><div class="step"><span>01</span><b>Reproduce it</b><p>Work out what is happening and when the problem appears.</p></div><div class="step"><span>02</span><b>Check the basics</b><p>Connectivity, logs, settings and whether the service is actually running.</p></div><div class="step"><span>03</span><b>Change one thing</b><p>Test a possible fix without losing track of what changed.</p></div><div class="step"><span>04</span><b>Check again</b><p>Verify the result, keep a note and roll back experiments if needed.</p></div></div></div></section>'''
about='''<section class="section" id="about"><div class="wrap about-band"><div><div class="eyebrow" style="color:#80d0c9">04 / ABOUT ME</div><h2>Learning by actually doing it.</h2><p>I started with my own devices and gradually turned that interest into a home lab. I like working out why something fails, fixing it and understanding the result. Some projects are useful every day; others are experiments that helped me learn.</p><p>I'm looking for an entry-level IT Support, Service Desk or junior infrastructure role where I can bring my hands-on experience, keep learning and help people solve problems.</p></div><div class="about-aside"><b>Outside IT</b><p>I've spent more than nine years in customer-facing retail, including a supervisor role. That's taught me how to communicate clearly, work under pressure, help colleagues and know when to escalate an issue.</p><b>Certification</b><small>CompTIA IT Fundamentals+ (ITF+)</small></div></div></section>'''
contact=f'''<section class="contact-zone" id="contact"><div class="wrap contact-box"><div><div class="eyebrow">05 / CONTACT</div><h2>Thanks for having a look.</h2><p>If you'd like to know more about a project, I'm happy to talk through what I built and how I tested it.</p></div><div class="contact-controls"><div class="actions"><a href="mailto:{ESC(DATA['contact_email'])}" class="btn btn-main">Email me ↗</a><button id="copy-email" type="button" class="btn btn-outline copy-email-btn" data-email="{ESC(DATA['contact_email'])}" aria-describedby="contact-email">Copy email address ⧉</button><a href="https://github.com/{ESC(DATA['github_username'])}" class="btn btn-outline" rel="noopener noreferrer">GitHub profile ↗</a></div><div class="contact-email-line"><span id="contact-email">{ESC(DATA['contact_email'])}</span><span id="copy-email-status" class="copy-status" role="status" aria-live="polite"></span></div></div></div></section><script defer src="assets/contact.js"></script>'''
(ROOT/'index.html').write_text(page('Home',hero+metrics+projects+skills+method+about+contact,desc='Jake Alford: independent IT projects covering Windows Server, Hyper-V, networking, Linux, monitoring, software development and troubleshooting.'),encoding='utf-8')
for p in P:
    def sec(label, body): return f'<div class="detail-block"><div class="section-kicker">{ESC(label)}</div>{body}</div>'
    blocks=[sec('Why I did it',f'<p>{ESC(p["goal"])}</p>'),sec('What I configured / built','<ul>'+''.join('<li>'+ESC(x)+'</li>' for x in p['work'])+'</ul>'),sec('What I verified','<ul>'+''.join('<li>'+ESC(x)+'</li>' for x in p['proof'])+'</ul>'),sec('What I learned','<p>'+ESC(p['learned'])+'</p>'),sec('Current status / next steps','<p>'+ESC(p['next'])+'</p>')]
    sidebar=f'''<aside class="detail-side"><div class="sidebar-card"><h3>Tools and technologies</h3><div class="tool-list">{''.join('<span>'+ESC(t)+'</span>' for t in p['tech'])}</div></div><div class="sidebar-card"><h3>Project status</h3><p class="status" style="display:inline-block">{ESC(p['status'])}</p><p class="muted" style="font-size:13px">Details last reviewed {ESC(p['updated'])}. Status reflects what was actually configured or tested.</p></div><a class="btn btn-outline" href="../index.html#projects">← Back to projects</a></aside>'''
    body=f'''<section class="project-hero"><div class="wrap"><a class="breadcrumb" href="../index.html#projects">← Back to all projects</a><div class="eyebrow" style="margin-top:32px">{ESC(p['category'])} / CASE STUDY</div><h1>{ESC(p['title'])}</h1><p class="lead">{ESC(p['lead'])}</p><div class="project-meta"><span class="pill">{ESC(p['status'])}</span><span class="pill">Independent project</span></div></div></section><div class="wrap detail-layout"><article class="detail-main">{''.join(blocks)}<div class="callout">This is personal project experience, not a claim of paid IT employment. I keep working systems, locally tested features and plans clearly separated.</div></article>{sidebar}</div>'''
    (ROOT/'projects'/f'{p["slug"]}.html').write_text(page(p['title'],body,prefix='../',desc=p['short']),encoding='utf-8')
(ROOT/'.nojekyll').write_text('',encoding='utf-8')
(ROOT/'assets'/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#102b39"/><text x="10" y="42" font-size="31" font-family="Arial,sans-serif" font-weight="bold" fill="#f6f5ef">JA</text></svg>',encoding='utf-8')
print(f'Generated homepage and {len(P)} project pages')
